const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry - Punjab and Haryana states from FAO dataset
  var states = ee.FeatureCollection("FAO/GAUL/2015/level1");
  var punjab = states.filter(ee.Filter.eq('ADM1_NAME', 'Punjab'));
  var haryana = states.filter(ee.Filter.eq('ADM1_NAME', 'Haryana'));
  var region = punjab.merge(haryana).union().geometry();

  // 2. Date range - November 2024
  var startDate = '2024-11-01';
  var endDate = '2024-11-30';

  // 3. Data acquisition - VIIRS Fire Detection (VNP14IMGML)
  var collection = ee.ImageCollection('NOAA/VIIRS/001/VNP14IMGML')
    .filterDate(startDate, endDate)
    .filterBounds(region)
    .select('FireMask');

  // 4. Check collection size
  var size = collection.size().getInfo();
  print('November 2024 VIIRS images:', size);

  if (size === 0) {
    print('<answer>C1</answer>');
    return;
  }

