  var fireMask = collection.map(function(img) {
    return img.gte(4); // All fire detections (low+nominal+high confidence)
  });

  // Sum all fire detections over the month
  var totalFire = fireMask.sum().rename('fire_detections');

  // 6. Count fire pixels
  var stats = totalFire.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  var fireCount = stats.get('fire_detections').getInfo();

  // 7. Validation and final answer
  if (fireCount === null || fireCount === undefined) {
    print('Calculation failed');
    print('<answer>C3</answer>');
